package io.invenlio.inventory;
import org.springframework.test.web.servlet.ResultActions;
import java.util.concurrent.*;
import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.context.*;import org.springframework.boot.testcontainers.service.connection.*;import org.springframework.boot.webmvc.test.autoconfigure.*;import org.springframework.dao.DataAccessException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import org.testcontainers.junit.jupiter.*;import org.testcontainers.postgresql.PostgreSQLContainer;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@Testcontainers @SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test")class InventoryIntegrationTest{
 static final UUID T=UUID.fromString("11111111-1111-4111-8111-111111111111"),P=UUID.fromString("30000000-0000-4000-8000-000000000001"),V=UUID.fromString("30000000-0000-4000-8000-000000000002"),W=UUID.fromString("30000000-0000-4000-8000-000000000003"),Z=UUID.fromString("30000000-0000-4000-8000-000000000004"),L=UUID.fromString("30000000-0000-4000-8000-000000000005");@Container @ServiceConnection static final PostgreSQLContainer DB=new PostgreSQLContainer("postgres:17.6-alpine");@Autowired JdbcTemplate db;@Autowired MockMvc mvc;
 @BeforeEach void seed(){db.execute("TRUNCATE inventory_ledger_entries,inventory_movements,inventory_balances");db.update("DELETE FROM warehouse_operational_locations");db.update("DELETE FROM warehouse_locations");db.update("DELETE FROM warehouse_zones");db.update("DELETE FROM warehouses");db.update("DELETE FROM catalog_barcodes");db.update("DELETE FROM catalog_product_variants");db.update("DELETE FROM catalog_products");db.update("DELETE FROM audit_events");db.update("DELETE FROM membership_roles");db.update("DELETE FROM role_permissions");db.update("DELETE FROM organization_memberships");db.update("DELETE FROM roles");db.update("DELETE FROM user_identities");db.update("DELETE FROM organizations");UUID u=UUID.randomUUID(),m=UUID.randomUUID(),r=UUID.randomUUID();db.update("INSERT INTO organizations(id,name,slug,status,default_locale,default_timezone,default_currency,created_at,updated_at,version)VALUES (?,?,?,'ACTIVE','en','UTC','EUR',now(),now(),0)",T,"T","t");db.update("INSERT INTO user_identities(id,keycloak_subject,status,created_at,updated_at)VALUES (?,?,'ACTIVE',now(),now())",u,"admin");db.update("INSERT INTO organization_memberships(id,tenant_id,user_identity_id,status,created_at,updated_at,version)VALUES (?,?,?,'ACTIVE',now(),now(),0)",m,T,u);db.update("INSERT INTO roles(id,tenant_id,name,system_role,created_at,updated_at,version)VALUES (?,?,?,false,now(),now(),0)",r,T,"INV");for(String p:List.of("inventory:read","inventory:adjust","inventory-ledger:read"))db.update("INSERT INTO role_permissions VALUES (?,?,?)",T,r,p);db.update("INSERT INTO membership_roles VALUES (?,?,?)",T,m,r);db.update("INSERT INTO catalog_products(id,tenant_id,name,status,base_unit,created_at,updated_at,version)VALUES (?,?,?,'ACTIVE','EA',now(),now(),0)",P,T,"Product");db.update("INSERT INTO catalog_product_variants(id,tenant_id,product_id,sku,normalized_sku,status,base_unit,option_signature,created_at,updated_at,version)VALUES (?,?,?,?,?,'ACTIVE','EA','DEFAULT',now(),now(),0)",V,T,P,"SKU","SKU");db.update("INSERT INTO warehouses(id,tenant_id,code,normalized_code,name,status,timezone,created_at,updated_at,version)VALUES (?,?,?,?,?,'ACTIVE','UTC',now(),now(),0)",W,T,"W","W","W");db.update("INSERT INTO warehouse_zones(id,tenant_id,warehouse_id,code,normalized_code,name,type,status,created_at,updated_at,version)VALUES (?,?,?,?,?,?,'STORAGE','ACTIVE',now(),now(),0)",Z,T,W,"Z","Z","Z");db.update("INSERT INTO warehouse_locations(id,tenant_id,warehouse_id,zone_id,code,normalized_code,type,status,scan_code,normalized_scan_code,created_at,updated_at,version)VALUES (?,?,?,?,?,?,'BIN','ACTIVE',?,?,now(),now(),0)",L,T,W,Z,"L","L","SCAN","SCAN");}
 @Test void adjustmentProjectsBalanceAndLedger()throws Exception{postAdjustment("one","10").andExpect(status().isOk()).andExpect(jsonPath("$.onHand").value(10.0));mvc.perform(get("/api/v1/inventory/balances").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$[0].onHand").value(10.0));mvc.perform(get("/api/v1/inventory/ledger").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$[0].quantityDelta").value(10.0));assertEquals(0,db.queryForObject("SELECT (SELECT on_hand_quantity FROM inventory_balances)-(SELECT sum(quantity_delta) FROM inventory_ledger_entries)",Integer.class));}
 @Test void identicalRetryIsIdempotentAndMismatchConflicts()throws Exception{postAdjustment("same","10").andExpect(status().isOk());postAdjustment("same","10").andExpect(status().isOk());assertEquals(1,db.queryForObject("SELECT count(*) FROM inventory_movements",Integer.class));postAdjustment("same","20").andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("IDEMPOTENCY_KEY_REUSED"));}
 @Test void insufficientStockIsAtomic()throws Exception{postAdjustment("open","5").andExpect(status().isOk());postAdjustment("bad","-6").andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("INSUFFICIENT_ON_HAND"));assertEquals(1,db.queryForObject("SELECT count(*) FROM inventory_movements",Integer.class));assertEquals(5,db.queryForObject("SELECT on_hand_quantity FROM inventory_balances",Integer.class));}
 @Test void zeroAndFractionalEachAreRejected()throws Exception{postAdjustment("zero","0").andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_INVENTORY_QUANTITY"));postAdjustment("fraction","1.5").andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_INVENTORY_QUANTITY"));assertEquals(0,db.queryForObject("SELECT count(*) FROM inventory_movements",Integer.class));}
 @Test void historyCannotBeUpdatedOrDeleted()throws Exception{postAdjustment("immutable","2").andExpect(status().isOk());assertThrows(DataAccessException.class,()->db.update("UPDATE inventory_ledger_entries SET quantity_delta=3"));assertThrows(DataAccessException.class,()->db.update("DELETE FROM inventory_movements"));}
@Test void authorizationAndInputBounds()throws Exception{mvc.perform(get("/api/v1/inventory/balances")).andExpect(status().isUnauthorized());mvc.perform(get("/api/v1/inventory/balances?size=101").with(token())).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_PAGINATION"));mvc.perform(get("/api/v1/inventory/ledger?sort=tenantId").with(token())).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_SORT"));mvc.perform(post("/api/v1/inventory/adjustments").with(token()).contentType("application/json").content(body("1"))).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("IDEMPOTENCY_KEY_REQUIRED"));}
 @Test void concurrentCreditsAndDebitsHaveNoLostUpdateOrNegativeStock()throws Exception{ExecutorService pool=Executors.newFixedThreadPool(30);try{CountDownLatch ready=new CountDownLatch(20),go=new CountDownLatch(1);List<Future<Integer>>credits=new ArrayList<>();for(int i=0;i<20;i++){int n=i;credits.add(pool.submit(()->{ready.countDown();go.await();return postAdjustment("credit-"+n,"1").andReturn().getResponse().getStatus();}));}ready.await();go.countDown();for(Future<Integer>f:credits)assertEquals(200,f.get());assertEquals(20,db.queryForObject("SELECT on_hand_quantity FROM inventory_balances",Integer.class));CountDownLatch ready2=new CountDownLatch(30),go2=new CountDownLatch(1);List<Future<Integer>>debits=new ArrayList<>();for(int i=0;i<30;i++){int n=i;debits.add(pool.submit(()->{ready2.countDown();go2.await();return postAdjustment("debit-"+n,"-1").andReturn().getResponse().getStatus();}));}ready2.await();go2.countDown();int ok=0,conflict=0;for(Future<Integer>f:debits){int s=f.get();if(s==200)ok++;if(s==409)conflict++;}assertEquals(20,ok);assertEquals(10,conflict);assertEquals(0,db.queryForObject("SELECT on_hand_quantity FROM inventory_balances",Integer.class));assertEquals(0,db.queryForObject("SELECT sum(quantity_delta) FROM inventory_ledger_entries",Integer.class));}finally{pool.shutdownNow();}}
 @Test void concurrentIdenticalRequestsCreateOneMovement()throws Exception{ExecutorService pool=Executors.newFixedThreadPool(12);try{CountDownLatch ready=new CountDownLatch(12),go=new CountDownLatch(1);List<Future<Integer>>calls=new ArrayList<>();for(int i=0;i<12;i++)calls.add(pool.submit(()->{ready.countDown();go.await();return postAdjustment("duplicate","3").andReturn().getResponse().getStatus();}));ready.await();go.countDown();for(Future<Integer>f:calls)assertEquals(200,f.get());assertEquals(1,db.queryForObject("SELECT count(*) FROM inventory_movements",Integer.class));assertEquals(3,db.queryForObject("SELECT on_hand_quantity FROM inventory_balances",Integer.class));}finally{pool.shutdownNow();}}
 @Test void permissionLifecycleWarehouseAndPrecisionRulesAreEnforced()throws Exception{db.update("DELETE FROM role_permissions WHERE permission_key='inventory:adjust'");postAdjustment("denied","1").andExpect(status().isForbidden());db.update("INSERT INTO role_permissions SELECT tenant_id,id,'inventory:adjust' FROM roles");postAdjustment("precision","0.0000001").andExpect(status().isBadRequest());db.update("UPDATE catalog_product_variants SET status='ARCHIVED' WHERE id=?",V);postAdjustment("archived","1").andExpect(status().isBadRequest());db.update("UPDATE catalog_product_variants SET status='ACTIVE' WHERE id=?",V);db.update("UPDATE warehouse_locations SET status='BLOCKED' WHERE id=?",L);postAdjustment("blocked","1").andExpect(status().isBadRequest());db.update("UPDATE warehouse_locations SET status='ACTIVE' WHERE id=?",L);UUID other=UUID.randomUUID();db.update("INSERT INTO warehouses(id,tenant_id,code,normalized_code,name,status,timezone,created_at,updated_at,version)VALUES (?,?,?,?,?,'ACTIVE','UTC',now(),now(),0)",other,T,"W2","W2","W2");mvc.perform(post("/api/v1/inventory/adjustments").with(token()).header("Idempotency-Key","cross-warehouse").contentType("application/json").content(body("1").replace(W.toString(),other.toString()))).andExpect(status().isBadRequest());assertEquals(0,db.queryForObject("SELECT count(*) FROM inventory_movements",Integer.class));}
 @Test void databaseTenantForeignKeysAndProjectionUniquenessAreEnforced()throws Exception{UUID foreignTenant=UUID.randomUUID();assertThrows(DataAccessException.class,()->db.update("INSERT INTO inventory_balances(tenant_id,variant_id,warehouse_id,location_id,on_hand_quantity,unit_code,updated_at,version)VALUES (?,?,?,?,1,'EA',now(),0)",foreignTenant,V,W,L));postAdjustment("unique","1").andExpect(status().isOk());assertThrows(DataAccessException.class,()->db.update("INSERT INTO inventory_balances(tenant_id,variant_id,warehouse_id,location_id,on_hand_quantity,unit_code,updated_at,version)VALUES (?,?,?,?,1,'EA',now(),0)",T,V,W,L));}
 private ResultActions postAdjustment(String key,String delta)throws Exception{return mvc.perform(post("/api/v1/inventory/adjustments").with(token()).header("Idempotency-Key",key).contentType("application/json").content(body(delta)));}private String body(String delta){return "{\"variantId\":\""+V+"\",\"warehouseId\":\""+W+"\",\"locationId\":\""+L+"\",\"quantityDelta\":\""+delta+"\",\"reason\":\"MANUAL_CORRECTION\"}";}private org.springframework.test.web.servlet.request.RequestPostProcessor token(){return jwt().jwt(j->j.subject("admin").claim("tenant_id",T.toString()));}
}
